        if (lineBarRight === BarLineStyle.LightHeavy) {
            width -= this.renderer.smuflMetrics.thickBarlineThickness + this.renderer.smuflMetrics.barlineSeparation;
        }
        cx = (cx | 0) + canvas.lineWidth / 2;
        cy = (cy | 0) + canvas.lineWidth / 2;
